<script lang="ts">
  import { t, dateTime, timeOnly } from "../../lib/ui";
  import { formatMinutes } from "../../lib/formatting";
  import { getLiveStatusLabel, getMatchStatusLabel } from "../../lib/session-labels";
  import { filterRowsByTag, deriveHandEntries, eventTypeCounts } from "../../lib/record-tools";
  import SortableFilterStack from "../../lib/common/SortableFilterStack.svelte";
  import AttendanceFilterPanel from "../../lib/common/AttendanceFilterPanel.svelte";
  import { settings } from "../../lib/stores";
  import StatusBadge from "../../lib/common/StatusBadge.svelte";
  import NameMatchingPanel from "../../lib/NameMatchingPanel.svelte";
  import { statusStyle, statusLabel } from "../../lib/status-style";
  export let view = "status", record: any = {}, state: any = {}, events: any[] = [], users: any[] = [], language = "en", configs: any = {}, mode = "generic", profile: any = null;
  export let onCaptureManual: () => void = () => {}; export let onCaptureHands: () => void = () => {};
  export let onDecision: (d: any) => Promise<void> = async () => {}; export let onRevert: (id: string) => Promise<void> = async () => {};
  export let onOverrides: (p?: any) => Promise<void> = async () => {}; export let onSelectProfile: (id: string) => Promise<void> = async () => {}; export let onModeChange: (mode: string) => Promise<void> = async () => {};
  let activeFilter = "", search = "", entryType = "", newest = true, ascending = true, filteredRows: any[] = [];
  const tLocal = (zh: string, en: string) => language === "zh-CN" ? zh : en;
  const statusDefs = [
    ["seen", "到过", "Seen", "seen"], ["full_present", "全程", "Full Present", "fullPresent"], ["late", "迟到", "Late", "late"], ["returned", "返回", "Returned", "returned"], ["left_early", "早退", "Left Early", "leftEarly"], ["missing", "缺席", "Absent", "missing"], ["ignored", "不计入", "Ignored", "ignored"], ["total", "总计", "Total", "total"],
  ];
  $: rows = record.rows || [];
  $: rosterMode = mode === "roster" && (configs.roster || []).length > 0;
  $: statItems = statusDefs.filter((d: any) => d[0] !== "full_present" || mode === "roster").map((d: any) => ({ id: d[0], label: t(d[1], d[2]), color: statusStyle(d[0]).color, count: d[0] === "total" ? (record.summary?.total ?? rows.length) : (record.summary?.[d[3]] ?? filterRowsByTag(rows, d[0]).length) }));
  $: movement = record.record?.movementEvents || record.movementEvents || [];
  $: visibleMovement = movement.filter((e: any) => (!entryType || (e.type || e.eventType) === entryType) && (!search || (e.participant?.screenName || "").toLowerCase().includes(search.toLowerCase()))).slice().sort((a: any,b: any) => (Date.parse(a.timestamp)-Date.parse(b.timestamp)) * (newest ? -1 : 1));
  $: counts = eventTypeCounts(movement);
  $: handEntries = deriveHandEntries(events, users);
  $: searchedHands = handEntries.filter((e: any) => !search || e.screenName.toLowerCase().includes(search.toLowerCase())).slice().reverse();
  $: pendingDecisions = (state.reconciliationDecisions || []).slice().reverse();
  $: settingsProfile = profile || (configs.profiles || []).find((p: any) => p.id === (state.selectedProfileId || record.record?.selectedProfileId)) || (configs.profiles || []).find((p: any) => p.id === "default-all");
  function statusTone(status: string) { return status === "fullPresent" || status === "present" || status === "inMeeting" ? "success" : status === "late" || status === "returnedAfterLongAbsence" ? "warning" : status === "missing" || status === "leftEarly" ? "danger" : "neutral"; }
  function rowStatusTags(row: any) {
    const tags = [];
    if (row.wasLate || row.currentStatus === 'late') tags.push('late');
    else if (row.currentStatus === 'present') tags.push(mode === 'roster' ? 'full_present' : 'seen');
    if (row.hasBeenSeen && !tags.includes('seen') && (row.wasLate || row.currentStatus !== 'present' || mode !== 'roster')) tags.push('seen');
    if (row.currentStatus === 'leftEarly') tags.push('left_early');
    if (row.currentStatus === 'returnedAfterLongAbsence') tags.push('returned');
    if (row.currentStatus === 'missing') tags.push('absent');
    return tags;
  }
  function movementLabel(type: string) { const labels: Record<string, [string,string]> = { join:["加入会议","Joined"],leave:["离开会议","Left"],joinedBefore:["启动时已在会议中","Present at start"],waitingRoomJoinFromOutside:["进入等候室","Entered waiting room"],waitingRoomJoinFromMeeting:["移至等候室","Moved to waiting room"],waitingRoomJoinedBefore:["启动时在等候室","Waiting at start"],waitingRoomLeave:["离开等候室","Left waiting room"] }; const pair=labels[type] || [type,type]; return t(pair[0],pair[1]); }
</script>

{#if view === "status"}
  <section class="status-view">
    <div class="summary-row"><SortableFilterStack items={statItems} active={activeFilter} onSelect={(id) => activeFilter = activeFilter === id ? '' : id} /><div class="mode-switch" aria-label={t("考勤模式", "Attendance mode")}><button class:chosen={mode === 'generic'} onclick={() => onModeChange('generic')}>{t("通用", "Generic")}</button><button class:chosen={mode === 'roster'} onclick={() => onModeChange('roster')}>{t("花名册", "Roster")}</button></div></div>
    <AttendanceFilterPanel rows={rows} roster={configs.roster || []} configGroups={[]} profile={settingsProfile} {mode} {language} initiallyOpen={!$settings.filterDefaultsClosed} {activeFilter} bind:ascending onActiveFilterChange={(value) => activeFilter = value} onRows={(value) => filteredRows = value} />
    <div class="table-wrap"><table class="attendance-table"><thead><tr><th>#</th><th>{t("姓名", "Name")}</th><th>{t("状态", "Status")} <button class="sort-toggle" onclick={() => ascending = !ascending}>↕</button></th><th>{t("位置", "Location")}</th><th>{t("分组", "Group")}</th><th>{t("首次加入", "First join")}</th><th>{t("最近进出", "Last entry/exit")}</th><th>{t("分钟", "Minutes")}</th></tr></thead><tbody>{#each filteredRows as r, i}<tr class:issue={r.wasLate || r.currentStatus === "leftEarly"}><td>{i+1}</td><td><b>{r.canonicalName || r.zoomName || "—"}</b>{#if r.zoomName && r.canonicalName && r.zoomName !== r.canonicalName}<small>{r.zoomName}</small>{/if}</td><td><div class="badges">{#each rowStatusTags(r) as tag}<StatusBadge status={tag} label={statusLabel(tag, language)} />{/each}{#if r.matchStatus === "unmatched" || r.matchStatus === "guest"}<StatusBadge label={getMatchStatusLabel(r.matchStatus, language as any)} />{/if}</div></td><td>{r.currentLocation === "meeting" ? t("会议中", "Meeting") : r.currentLocation === "waiting-room" ? t("等候室", "Waiting room") : "—"}</td><td>{r.group || "—"}</td><td>{r.firstJoinAt ? timeOnly(r.firstJoinAt) : "—"}</td><td>{r.lastSeenAt ? timeOnly(r.lastSeenAt) : "—"}</td><td>{formatMinutes(r.totalPresenceMinutes)}</td></tr>{:else}<tr><td colspan="8" class="empty">{t("等待参与者事件…", "Waiting for participant events…")}</td></tr>{/each}</tbody></table></div>
  </section>
{:else if view === "matching"}
  <NameMatchingPanel rows={rows} decisions={state.reconciliationDecisions || []} roster={configs.roster || []} aliases={configs.aliases || []} nameChanges={record.record?.nameChangeEvents || []} language={language} {onDecision} {onRevert} />
{:else if view === "names"}
  <section class="log-view"><h2>{t("名称变更", "Name Changes")} <small>{(record.record?.nameChangeEvents || []).length}</small></h2>{#each [...(record.record?.nameChangeEvents || [])].reverse() as item}<article class="event-row"><time>{dateTime(item.timestamp)}</time><b>{item.previousScreenName || item.previous_screen_name || "—"}</b><span>→</span><b>{item.nextScreenName || item.next_screen_name || "—"}</b></article>{:else}<p class="empty">{t("没有名称变更", "No name changes")}</p>{/each}</section>
{:else if view === "info"}
  <section class="settings-view"><div class="setting-cards"><article><small>{t("迟到阈值", "Late threshold")}</small><b>{record.record?.lateAfterMinutes ?? settingsProfile?.lateAfterMinutes ?? "—"} {t("分钟", "min")}</b></article><article><small>{t("返回窗口", "Return window")}</small><b>{record.record?.returnWindowMinutes ?? settingsProfile?.returnWindowMinutes ?? "—"} {t("分钟", "min")}</b></article><article><small>{t("选择的配置", "Selected profile")}</small><b>{settingsProfile?.name || state.selectedProfileId || "—"}</b></article><article><small>{t("包含的小组", "Included groups")}</small><b>{(settingsProfile?.includedSubgroups || []).join(", ") || t("全部", "All")}</b></article></div><div class="profile-actions"><label>{t("选择考勤配置", "Attendance profile")}<select value={state.selectedProfileId || "default-all"} onchange={(e) => onSelectProfile(e.currentTarget.value)}>{#each (configs.profiles || []).filter((p: any) => p.active) as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button onclick={() => onOverrides()}>{t("应用配置覆盖", "Apply profile overrides")}</button></div></section>
{:else if view === "manual"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("手动考勤记录", "Manual Attendance")}</h2><p>{t("捕获并查看当前参与者列表。", "Capture and review the current participant list.")}</p></div><button class="primary" onclick={onCaptureManual}>{t("捕获考勤", "Capture Attendance")}</button></div><p class="subheading">{t("已捕获", "Captured")} {state.manualSnapshots?.length || 0} {t("次", "times")}</p>{#each [...(state.manualSnapshots || [])].reverse() as snapshot, si}<details class="snapshot" open={si === 0}><summary><b>{dateTime(snapshot.timestamp)}</b><span>{t("总计", "Total")} {snapshot.participants?.length || 0} {t("位参与者", "participants")}</span></summary><div class="table-wrap"><table><thead><tr><th>#</th><th>{t("姓名", "Name")}</th><th>{t("位置", "Location")}</th><th>{t("匹配", "Match")}</th></tr></thead><tbody>{#each snapshot.participants || [] as p, i}<tr><td>{i+1}</td><td>{p.screenName || "—"}</td><td>{p.location === "meeting" ? t("会议中", "Meeting") : p.location === "waiting-room" ? t("等候室", "Waiting room") : p.location}</td><td>{p.matchedCanonicalName || getMatchStatusLabel(p.matchStatus, language as any)}</td></tr>{/each}</tbody></table></div></details>{:else}<p class="empty">{t("尚无手动考勤记录", "No manual attendance records yet")}</p>{/each}</section>
{:else if view === "entry"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("进出记录", "Entry/Exit Logs")} <small>{movement.length}</small></h2><p>{t("查看加入、离开和等候室事件。", "Review join, leave, and waiting room events.")}</p></div></div><div class="event-filters"><input aria-label={t("搜索名称", "Search names")} placeholder={t("搜索名称…", "Search names…")} bind:value={search} /><select bind:value={entryType}><option value="">{t("所有事件", "All events")} · {movement.length}</option>{#each Object.entries(counts) as [type,count]}<option value={type}>{movementLabel(type)} · {count}</option>{/each}</select><button onclick={() => newest = !newest}>{newest ? t("最新优先", "Newest first") : t("最早优先", "Oldest first")}</button></div><div class="table-wrap"><table><thead><tr><th>{t("时间", "Time")}</th><th>{t("姓名", "Name")}</th><th>{t("事件类型", "Event type")}</th></tr></thead><tbody>{#each visibleMovement as event}<tr><td>{timeOnly(event.timestamp)}</td><td><b>{event.participant?.screenName || "—"}</b></td><td><StatusBadge label={movementLabel(event.type || event.eventType)} tone={(event.type || "").toLowerCase().includes("leave") ? "warning" : "success"} /></td></tr>{:else}<tr><td colspan="3" class="empty">{t("没有进出事件", "No entry or exit events")}</td></tr>{/each}</tbody></table></div></section>
{:else if view === "hands"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("举手跟踪", "Raise Hand")}</h2><p>{t("查看举手事件并捕获当前举手列表。", "Review hand events and capture the current raised hands.")}</p></div><button class="primary" onclick={onCaptureHands}>{t("捕获举手记录", "Capture Raise Hand Records")}</button></div><div class="hand-current"><h3>{t("当前举手", "Current Hand Raises")} <small>{users.filter((u: any) => u.raisedHand || u.raised_hand).length} {t("人", "people")}</small></h3><div class="hand-chips">{#each users.filter((u: any) => u.raisedHand || u.raised_hand) as user}<StatusBadge label={user.name || "—"} tone="success" />{:else}<span class="muted">{t("目前没有举手", "No hands raised right now")}</span>{/each}</div></div><div class="event-filters"><input placeholder={t("搜索姓名…", "Search names…")} bind:value={search} /><span>{searchedHands.length} {t("条记录", "records")}</span></div><div class="table-wrap"><table><thead><tr><th>{t("时间", "Time")}</th><th>{t("姓名", "Name")}</th><th>{t("状态", "Status")}</th></tr></thead><tbody>{#each searchedHands as event}<tr><td>{timeOnly(event.timestamp)}</td><td><b>{event.screenName}</b></td><td><StatusBadge label={event.action === "raise" ? t("已举手", "Raised") : t("已放下", "Lowered")} tone={event.action === "raise" ? "success" : "neutral"} /></td></tr>{:else}<tr><td colspan="3" class="empty">{t("没有举手事件", "No raise-hand events")}</td></tr>{/each}</tbody></table></div><h3 class="section-heading">{t("举手记录快照", "Raise Hand Captures")}</h3>{#each [...(state.raiseHandCaptures || [])].reverse() as capture}<article class="event-row"><time>{dateTime(capture.timestamp)}</time><b>{capture.totalCount} {t("人", "people")}</b><span>{(capture.screenNames || []).join(", ")}</span></article>{:else}<p class="empty">{t("尚无举手快照", "No raise-hand captures yet")}</p>{/each}</section>
{:else if view === "operations"}
  <section class="log-view"><div class="view-heading"><div><h2>{t("操作面板", "Operations")}</h2><p>{t("查看本场会议的匹配与协调决定。", "Review matching and reconciliation decisions for this meeting.")}</p></div></div><div class="event-filters"><span>{t("已记录决定", "Recorded decisions")} · {pendingDecisions.length}</span><button onclick={onCaptureManual}>{t("捕获考勤", "Capture Attendance")}</button><button onclick={onCaptureHands}>{t("捕获举手", "Capture Raised Hands")}</button></div>{#each pendingDecisions as decision}<article class="event-row"><time>{dateTime(decision.createdAt)}</time><b>{decision.zoomName || "—"}</b><StatusBadge label={decision.action} /><span>{decision.canonicalName || ""}</span></article>{:else}<p class="empty">{t("尚无协调决定", "No reconciliation decisions yet")}</p>{/each}</section>
{:else if view === "settings"}
  <section class="settings-view"><h2>{t("会议设置", "Meeting Settings")}</h2><div class="setting-cards"><article><small>{t("迟到阈值", "Late threshold")}</small><b>{record.record?.lateAfterMinutes ?? settingsProfile?.lateAfterMinutes ?? "—"} {t("分钟", "min")}</b></article><article><small>{t("返回窗口", "Return window")}</small><b>{record.record?.returnWindowMinutes ?? settingsProfile?.returnWindowMinutes ?? "—"} {t("分钟", "min")}</b></article><article><small>{t("选择的配置", "Selected profile")}</small><b>{settingsProfile?.name || state.selectedProfileId || "—"}</b></article><article><small>{t("包含的小组", "Included groups")}</small><b>{(settingsProfile?.includedSubgroups || []).join(", ") || t("全部", "All")}</b></article></div><label class="profile-select">{t("考勤配置", "Attendance profile")}<select value={state.selectedProfileId || "default-all"} onchange={(e) => onSelectProfile(e.currentTarget.value)}>{#each (configs.profiles || []).filter((p: any) => p.active) as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button onclick={() => onOverrides()}>{t("应用配置覆盖", "Apply profile overrides")}</button></section>
{/if}

<style>
 .status-view,.log-view,.settings-view{min-width:0}.summary-row{display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--line);padding:4px 0}.mode-switch{display:flex;flex:none;background:#f4f6fa;border-radius:7px;padding:2px}.mode-switch button{min-height:27px;padding:3px 9px;border:0;background:transparent;font-size:10px}.mode-switch button.chosen{background:white;color:var(--accent);box-shadow:var(--shadow-card)}.event-filters,.view-heading,.profile-actions{display:flex;align-items:center;gap:8px;margin:8px 0}.event-filters input{min-height:30px!important;padding:6px 9px!important;flex:1}.event-filters span{font-size:10px;color:var(--muted);white-space:nowrap}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:7px;background:#fff}table{width:100%;border-collapse:collapse;font-size:11px;text-align:left}th{position:sticky;top:0;background:#f4f6fa;color:#596273;font-size:10px;text-transform:uppercase;letter-spacing:.35px}th,td{padding:7px 9px;border-bottom:1px solid var(--line);white-space:nowrap}td{height:36px}tbody tr:last-child td{border-bottom:0}tbody tr.issue{background:#fffaf1}td b{font-weight:700}td small{display:block;color:var(--muted);font-size:9px}.badges{display:flex;gap:4px}.empty{text-align:center;color:var(--muted);padding:22px}.log-view h2,.settings-view h2{font-size:14px;margin:10px 0 4px}.log-view h2 small{font-size:10px;color:var(--muted);font-weight:400}.view-heading{justify-content:space-between;align-items:center}.view-heading h2{margin:0}.view-heading p{margin:4px 0;color:var(--muted);font-size:11px}.view-heading button{min-height:30px}.subheading{font-size:11px;color:var(--muted);margin:10px 0}.snapshot{border:1px solid var(--line);border-radius:7px;margin:8px 0;background:white}.snapshot summary{display:flex;gap:14px;align-items:center;cursor:pointer;padding:10px;font-size:11px}.snapshot summary span{color:var(--muted)}.event-row{display:flex;align-items:center;gap:10px;min-height:34px;padding:6px 8px;border-bottom:1px solid var(--line);font-size:11px}.event-row:last-child{border-bottom:0}.event-row time{min-width:145px;color:var(--muted);font-size:10px}.event-row span:last-child{margin-left:auto}.setting-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:10px 0}.setting-cards article{display:grid;gap:5px;padding:9px;border:1px solid var(--line);border-radius:7px;background:white;min-width:0}.setting-cards small{font-size:9px;color:var(--muted)}.setting-cards b{font-size:11px;overflow-wrap:anywhere}.profile-actions label,.profile-select{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted)}.profile-actions select,.profile-select select{min-height:30px!important;padding:5px!important}.hand-current{padding:10px 0;border-bottom:1px solid var(--line)}.hand-current h3,.section-heading{font-size:12px;margin:0 0 8px}.hand-current h3 small{margin-left:5px;color:var(--muted);font-weight:400}.hand-chips{display:flex;gap:6px;flex-wrap:wrap}.muted{font-size:11px;color:var(--muted)}
 @media(max-width:900px){.setting-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.event-row{flex-wrap:wrap}.event-row time{min-width:110px}}
</style>
